                            if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                                seen.add((ny, nx)); q.append((ny, nx))
                out.append(cells)
    return out


def wave_fill_right(grid, fill=1, bg=None, marker=None):
    """Zigzag wave of marker runs: merge components joined by one diagonal bg gap (dr=1, dc=2); each row whose rightmost marker column equals its component's max column fills bg cells to the right edge with `fill` -- solid if the marker extends left of the tip or the cell directly above the tip is a marker, else every other column."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    if bg is None:
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    if marker is None:
        marker = next(c for c in {v for row in grid for v in row} if c != bg)
    pts = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == marker}
    parent = {p: p for p in pts}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    def uni(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb
    for i, j in pts:
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                if (i + di, j + dj) in pts: uni((i, j), (i + di, j + dj))
    for i, j in pts:  # knight bridges across one shared background gap (horizontal-dominant)
        for di, dj in ((1, 2), (1, -2), (-1, 2), (-1, -2)):
            if (i + di, j + dj) not in pts: continue
            bridged = False
            for a in range(min(i, i + di), max(i, i + di) + 1):
                for b in range(min(j, j + dj), max(j, j + dj) + 1):
                    if (a, b) in pts or not (0 <= a < h and 0 <= b < w): continue
                    if grid[a][b] == bg and max(abs(a - i), abs(b - j)) <= 1 and max(abs(a - i - di), abs(b - j - dj)) <= 1:
                        bridged = True
            if bridged: uni((i, j), (i + di, j + dj))
    comps = {}
    for p in pts: comps.setdefault(find(p), []).append(p)
    comp_of = {cell: root for root, cells in comps.items() for cell in cells}
    out = [row[:] for row in grid]
    for i in range(h):
        mc = max((j for j, v in enumerate(grid[i]) if v == marker), default=-1)
        if mc < 0 or mc == w - 1 or (i, mc) not in comp_of: continue
        comp = comps[comp_of[(i, mc)]]
        mr = max(j for _, j in comp)
        fire = mc == mr
        if not fire and mc == mr - 1:
            rstar = min(r for r, c2 in comp if c2 == mr)
            if i == rstar + 1 and grid[rstar][mr - 1] == bg: fire = True
        if not fire: continue
        solid = (mc > 0 and grid[i][mc - 1] == marker) or (i > 0 and grid[i - 1][mc] == marker)
        for c in range(mc + 1, w):
            if ((c - mc) % 2 == 0 or solid) and out[i][c] == bg: out[i][c] = fill
    return out


def fill_periodic_stripes(grid):
    """Fill the whole grid with the periodic stripe coloring implied by its nonzero cells: colors lie on parallel (main or anti) diagonals repeating with some period."""
    h, w = len(grid), len(grid[0])
    for key in (lambda i, j: j - i, lambda i, j: i + j):
        for p in range(1, w + 1):
            P, ok = {}, True
            for i in range(h):
                for j in range(w):
                    if grid[i][j]:
                        k = key(i, j) % p
                        if k in P and P[k] != grid[i][j]:
                            ok = False
                            break
                        P[k] = grid[i][j]
                if not ok:
                    break
            if ok and len(P) == p:
                return [[P[key(i, j) % p] for j in range(w)] for i in range(h)]
    return grid


def fill_box_interiors(grid, fill):
    """Fill the interior of every closed rectangle of a single frame color with fill."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    frame = next(c for c in cnt if c != bg)
    g = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if g[r][c] != frame: continue
            for rb in range(r + 1, h):
                for cb in range(c + 1, w):
                    if g[rb][c] == g[r][cb] == g[rb][cb] == frame                        and all(g[r][j] == frame and g[rb][j] == frame for j in range(c, cb + 1))                        and all(g[i][c] == frame and g[i][cb] == frame for i in range(r, rb + 1))                        and all(g[i][j] == bg for i in range(r + 1, rb) for j in range(c + 1, cb)):
                        for i in range(r + 1, rb):
                            for j in range(c + 1, cb):
                                g[i][j] = fill
    return g


def solid_lines(grid):
    """Indices of full rows and full columns that are one nonzero color throughout: ('r', i) / ('c', j)."""
    h, w = len(grid), len(grid[0])
    out = [('r', i) for i in range(h) if len(set(grid[i])) == 1 and grid[i][0] != 0]
    out += [('c', j) for j in range(w) if len({row[j] for row in grid}) == 1 and grid[0][j] != 0]
    return out

def overlap_half(grid, color=2):
    """Split the grid at the solid separator line that leaves two equal halves; cells nonzero in both halves become color."""
    for kind, k in solid_lines(grid):
        if kind == 'r':
            top, bot = grid[:k], grid[k + 1:]
            if len(top) == len(bot) and len(top) > 0:
                return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(top, bot)]
        else:
            left = [row[:k] for row in grid]
            right = [row[k + 1:] for row in grid]
            if len(left[0]) == len(right[0]) and len(left[0]) > 0:
                return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
    raise ValueError('no separating solid line')


def recolor_scatter_to_bg(grid):
    """Each cell of the scattered (minority) color takes the background (majority) color, and the background becomes 0."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    return [[0 if v == bg else bg for v in row] for row in grid]

def shift_colors_down(grid):
    """Sorted distinct colors shift down one rank: the smallest becomes 0, each other color becomes the next smaller one."""
    s = sorted({v for row in grid for v in row})
    m = {s[0]: 0}
    for k in range(1, len(s)):
        m[s[k]] = s[k-1]
    return [[m[v] for v in row] for row in grid]

def remap_min_to_zero(grid):
    """The grid with its smallest nonzero color mapped to 0 and the other colors shifted one rank down."""
    s = sorted({v for row in grid for v in row} - {0})
    if not s:
        return [row[:] for row in grid]
    m = {s[0]: 0}
    for k in range(1, len(s)):
        m[s[k]] = s[k-1]
    return [[m[v] for v in row] for row in grid]


def demote_minority(grid, base=5):
    """Color base (default 5) becomes the grid's other color, and that other color becomes 0."""
    other = next(k for k in {v for row in grid for v in row} if k != base)
    return [[other if v == base else 0 for v in row] for row in grid]

def complete_frame(grid, fill=2):
    """Complete the rectangle frame drawn by the non-background markers: every background cell on the markers' bounding-box perimeter becomes `fill`, as does any background cell completing a one-cell gap between two runs of markers in a row or column."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    mk = {(i, j) for i, r in enumerate(grid) for j, v in enumerate(r) if v != bg}
    t, l = min(i for i, _ in mk), min(j for _, j in mk)
    b, r2 = max(i for i, _ in mk), max(j for _, j in mk)
    perim = {(i, j) for i in range(t, b + 1) for j in (l, r2)} | \
            {(i, j) for i in (t, b) for j in range(l, r2 + 1)}
    out = [row[:] for row in grid]
    def m(i, j):
        return (i, j) in mk
    for i in range(h):
        for j in range(w):
            if grid[i][j] != bg:
                continue
            if (i, j) in perim or \
               (m(i, j-1) and m(i, j-2) and m(i, j+1) and m(i, j+2)) or \
               (m(i-1, j) and m(i-2, j) and m(i+1, j) and m(i+2, j)):
                out[i][j] = fill
    return out

